AV=[['拉丁 avere 渴望、热切想要','对某件事有很强的欲望']]
AVID=AV+[['拉丁 avidus → 法语 avide → 英语 avid；亦受较早 avidity 逆构影响','热切的；如饥似渴地投入']]
AVARICE=AV+[['拉丁 avarus 贪婪的 → avaritia → 古法语 avarice → 英语 avarice','特别想占有财富 → 贪财']]
AVARICIOUS=AVARICE[:-1]+[['拉丁 avarus → avaritia → 古法语 avarice → avaricios → 英语 avaricious','贪财 → 贪婪、吝啬的']]
SCANDAL=[['希腊 skandalon 陷阱、绊脚物；比喻道德上的绊倒','让人跌倒 → 冒犯、使人失足'],['晚期拉丁 scandalum → 法语 scandale → 英语 scandal','冒犯、名誉受损 → 丑闻；现代词可能是重新借入']]
SCANDALIZE=[['希腊 skandalon → skandalizein → 教会拉丁 scandalizare','使人绊倒、使人冒犯'],['古法语 scandaliser → 英语 scandalize','使名誉受损的旧义 → 使人因不当行为震惊、愤慨']]
SCANDALOUS=[['希腊 skandalon → 教会拉丁 scandalum → 中世纪拉丁 scandalosus','使人道德上绊倒 → 令人羞耻、冒犯的'],['古法语相关形容词〔现代 scandaleux〕→ 英语 scandalous','可耻、令人震惊的；英语形容词有独立借入路线']]
SLANDER=[['希腊 skandalon → 拉丁 scandalum → 古法语 escandle / escandre → esclandre','冒犯、丑事 → 损害名誉的言论'],['盎格鲁法语 esclaundre → 英语 slander〔名词〕；法语 esclandrer → 英语动词','并列借入名词与动词：诽谤；恶意毁损名誉']]
W += [
E('avid','/ˈævɪd/','热切的；痴迷的；渴求的','对喜欢的东西总想再多来一点，像读完一本又迫不及待读下一本。','法语 avide 接拉丁 avidus 和 avere 渴望；英语也受较早名词 avidity 逆构影响。',AVID,'an avid reader 是热爱阅读的人；avid for news 是急切想得到消息。现代常可称赞兴趣浓厚，不必带贪婪的责备。','an avid reader；an avid fan；an avid collector；avid for information。','avaricious 特别批评贪财；avid 可以积极形容求知与兴趣。eager 常说眼前愿望，avid 常突出持续的强烈兴趣。',('She is an avid reader of travel writing.','她非常爱读旅行文学。'),('The audience was avid for news of the missing expedition.','听众急切盼望得知失踪探险队的消息。'),sources=['https://www.etymonline.com/word/avid','https://www.oxfordlearnersdictionaries.com/definition/english/avid']),
E('avidly','/ˈævɪdli/','热切地；如饥似渴地；兴致勃勃地','注意力紧紧跟着喜欢的事，愿意一直读、听或看下去。','avid + -ly；把强烈兴趣变成动作的方式。',AVID+[['英语 avid + -ly → avidly','热切的 → 热切地投入某事']],'read avidly 是如饥似渴地读；follow a story avidly 是紧紧追着消息看。并不只表示阅读速度快。','read avidly；listen avidly；follow avidly；watch avidly。','quickly 是快；avidly 是兴趣很强。可以慢慢读却读得 avidly。',('He read the old letters avidly, hoping to learn more about his family.','他如饥似渴地读着旧信，希望多了解一点家族往事。'),('Fans followed every update avidly.','粉丝们热切关注每一条新消息。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/avidly','https://en.wiktionary.org/wiki/avidly#English']),
E('avidity','/əˈvɪdɪti/','热切；渴望；急切投入〔正式〕','把很想要、很投入的那股劲当作一种状态来描述。','古法语 avidite 或拉丁 aviditas 的名词借入；英语名词早于 avid，现代 avid + -ity 的分析不能代替历史顺序。',AV+[['拉丁 avidus → aviditas → 古法语 avidite 或拉丁直接来源 → 英语 avidity','热切渴望；名词在英语中的记录早于 avid']],'with avidity 是热切地，常见于较正式叙述。生物医学里也有结合强度方面的专门义，普通阅读先抓欲望与兴趣的强烈程度。','with avidity；read with avidity；an avidity for knowledge。','eagerness 更日常；avidity 更书面。avarice 通常是负面的贪财，avidity 不限于财富。',('She read each new chapter with avidity.','她热切地读着每一章新内容。'),('His avidity for knowledge never faded.','他对知识的热望从未消退。'),sources=['https://www.etymonline.com/word/avidity','https://en.wiktionary.org/wiki/avidity#English']),
E('avarice','/ˈævərɪs/','贪财；贪婪','财富已经不少，却还想攥住更多，欲望压过了对人的顾虑。','拉丁 avere 渴望 → avarus 贪婪的 → avaritia，经古法语 avarice 借入英语。',AVARICE,'driven by avarice 是被贪欲驱使。词偏正式，小说和道德评论里常见，尤其强调占有财富的过度欲望。','driven by avarice；human avarice；an act of avarice。','ambition 可以是上进心；avarice 明确带批评，不能把努力赚钱的人一律称为受 avarice 驱使。',('The fable shows how avarice destroys a friendship.','寓言展示了贪财如何毁掉一段友谊。'),('The narrator blames the betrayal on avarice.','叙述者把那次背叛归咎于贪欲。'),sources=['https://www.etymonline.com/word/avarice','https://www.oxfordlearnersdictionaries.com/definition/english/avarice']),
E('avaricious','/ˌævəˈrɪʃəs/','贪财的；贪婪的','心里盘算着怎样拿得更多、留得更多，常带不肯顾及他人的意思。','古法语 avaricios 来自 avarice；英语借入整个形容词。现代能与 avarice 对照，但不是简单保留其末尾 e 再加 -ous。',AVARICIOUS,'an avaricious landlord 是贪婪房东；an avaricious character 可形容小说里只认钱的角色。评价明显负面且较书面。','an avaricious character；an avaricious landlord；avaricious motives。','avid 是对某事热切；avaricious 特别偏向贪财。thrifty 是节俭，通常正面，不等于 avaricious。',('The story’s avaricious merchant values money above every friendship.','故事里那个贪婪商人把钱看得比所有友谊都重。'),('She refused to work for such an avaricious employer.','她拒绝为这样一个贪婪的雇主工作。'),sources=['https://www.etymonline.com/word/avaricious','https://www.oxfordlearnersdictionaries.com/definition/english/avaricious']),
E('avariciously','构词参考 /ˌævəˈrɪʃəsli/','贪婪地；贪财地','盯着钱财或利益不放，行动里流露出想占有更多的欲望。','avaricious + -ly；词典列有这一副词，读音按已核实的形容词加 /li/ 给出构词参考。',AVARICIOUS+[['英语 avaricious + -ly → avariciously','贪财的 → 贪婪地看待或追逐']],'look avariciously at something 是贪婪地看着某物。词较正式，适合人物描写；日常常直接用 greedily。','look avariciously at；eye avariciously；pursue wealth avariciously。','avidly 可表示对知识的热爱；avariciously 带贪欲评价，不适合单纯称赞学习投入。',('The miser looked avariciously at the pile of coins.','守财奴贪婪地盯着那堆硬币。'),('The villain pursued wealth avariciously, ignoring the damage he caused.','反派贪婪地追逐财富，不顾自己造成的伤害。'),sources=['https://www.merriam-webster.com/dictionary/avaricious','https://www.collinsdictionary.com/dictionary/english/avariciously']),
E('scandal','/ˈskændəl/','丑闻；令人愤慨的事；丑事传闻','某件被认为不光彩的事进入公众视野，造成名誉受损和强烈议论。','希腊 skandalon 原指陷阱、绊脚物，进入宗教语境后比喻道德失足；经拉丁、法语传为丑闻。',SCANDAL,'a financial scandal 是财务丑闻；a scandal breaks 是丑闻曝光。这个称呼说明事件引发争议与名誉问题，具体事实仍要看证据。','a political scandal；a financial scandal；a scandal breaks；be involved in a scandal。','rumour 是未经证实的传言；scandal 是引起耻辱或愤慨的事件或议论。丑闻可能含真事、指控和传闻，不能仅凭标签判断每项细节已证实。',('The financial scandal forced the board to order an independent review.','财务丑闻迫使董事会要求开展独立审查。'),('The novel begins when a family scandal becomes public.','小说从一桩家族丑事公开开始。'),sources=['https://www.etymonline.com/word/scandal','https://www.oxfordlearnersdictionaries.com/definition/english/scandal']),
E('scandalize','/ˈskændəlaɪz/','使震惊、愤慨；冒犯道德观念','做出某人认为太出格的事，让对方惊呼怎么能这样。','经古法语 scandaliser、教会拉丁 scandalizare 接希腊 skandalizein 使人绊倒、冒犯；动词独立借入，不能只画较晚现代 scandal + -ize。',SCANDALIZE,'scandalize the neighbours 是让邻居觉得太出格。它特别涉及道德、礼俗和体面观念，不是任何出乎意料都能用。','scandalize society；scandalize the neighbours；be scandalized by。','surprise 是一般吃惊；scandalize 是觉得某事不应该发生、很不体面。英式也常写 scandalise。',('Her unconventional lifestyle scandalized the small town.','她不循常规的生活方式让小镇居民大感震惊。'),('The character’s rude speech was meant to scandalize the guests.','这个角色故意讲粗鲁的话，让宾客觉得被冒犯。'),sources=['https://www.etymonline.com/word/scandalize','https://www.oxfordlearnersdictionaries.com/definition/english/scandalize']),
E('scandalized','/ˈskændəlaɪzd/','因觉得不当而震惊、愤慨的','自己是被震到的那个人，觉得别人的行为越过了能接受的界线。','scandalize + -ed；可作过去分词和形容词，形容人的反应。',SCANDALIZE+[['英语 scandalize + -ed → scandalized','使人惊愕 → 感到被冒犯、震惊的']],'a scandalized expression 是震惊而不以为然的表情；be scandalized by the cost 可夸张说贵得难以接受。','be scandalized by；look scandalized；a scandalized expression。','scandalous 描写引发愤慨的事，scandalized 描写感到愤慨的人。不要把 a scandalized price 当成离谱价格。',('She looked scandalized when he put his shoes on the table.','他把鞋放到桌上时，她露出一副难以接受的神情。'),('The visitors were scandalized by the hotel’s extra charges.','游客们对酒店额外收费之离谱感到愤慨。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/scandalize','https://en.wiktionary.org/wiki/scandalized#English']),
E('scandalous','/ˈskændələs/','可耻的；令人愤慨的；离谱的','事情糟糕到让人觉得不能接受，不只是普通的小缺点。','古法语形容词接中世纪拉丁 scandalosus，源于 scandalum；有独立借入路线，不是必须等现代英语 scandal 出现后才加 -ous。',SCANDALOUS,'scandalous behaviour 是可耻行为；scandalous prices 可夸张说价格离谱。它不要求真的已经有媒体报道的丑闻。','scandalous behaviour；a scandalous waste；scandalous prices；scandalous neglect。','scandalized 是受到冒犯、感到愤慨；scandalous 是让人愤慨。outrageous 在很多普通场景中可近义。',('Leaving the building unsafe for years was scandalous neglect.','多年放任这栋楼不安全，是令人愤慨的失职。'),('They charge scandalous prices for a simple cup of coffee.','一杯普通咖啡，他们却卖出离谱的高价。'),sources=['https://www.etymonline.com/word/scandalous','https://www.oxfordlearnersdictionaries.com/definition/english/scandalous']),
E('scandalously','/ˈskændələsli/','可耻地；离谱地；令人愤慨地','用很强烈的态度说某种做法或程度不该被接受。','scandalous + -ly；既修饰行为，也可加强 low、high、expensive 等形容词。',SCANDALOUS+[['英语 scandalous + -ly → scandalously','令人愤慨的 → 以这种方式或达到这种程度']],'scandalously low pay 是低得令人愤慨的工资；behave scandalously 是行为出格。重点是说话人的强烈否定评价。','scandalously low；scandalously expensive；behave scandalously；be scandalously neglected。','extremely 只加强程度；scandalously 加上不应如此、不能接受的判断。',('The workers were scandalously underpaid.','工人们拿到的工资低得令人愤慨。'),('The repair was scandalously expensive for such a simple job.','这么简单的一项维修，收费却高得离谱。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/scandalously','https://en.wiktionary.org/wiki/scandalously#English']),
E('slander','英 /ˈslɑːndə/；美 /ˈslændər/','诽谤；恶意中伤；造谣损害名誉','用不实的话让别人名声变坏，重点是话不实且伤害名誉。','古法语 esclandre、盎格鲁法语 esclaundre 接拉丁 scandalum；动词也有法语 esclandrer 借入路线。它与 scandal 是同源的不同借词，不是现代 scandal 随便变音。',SLANDER,'spread slander 是散布中伤言论；slander someone 是诽谤某人。普通词典常区分口头 slander 与书面 libel，具体法律分类随地区制度而异。','slander someone；spread slander；malicious slander；a slander against。','criticism 可以有事实依据；slander 强调不实的名誉攻击。scandal 是丑闻，两词虽同源，含义并不相同。',('The false accusation was intended to slander her.','那项虚假指控意在诽谤她。'),('He rejected the story as malicious slander.','他否认那个说法，称其为恶意中伤。'),sources=['https://www.etymonline.com/word/slander','https://www.oxfordlearnersdictionaries.com/definition/english/slander_1']),
E('slanderous','英 /ˈslɑːndərəs/；美 /ˈslændərəs/','诽谤性的；恶意中伤的','言论把不实的坏事扣到别人头上，损害对方名誉。','slander + -ous；前面的词经法语传来，后面的 -ous 让它能直接修饰 remark、claim 等名词。',SLANDER+[['英语 slander + -ous → slanderous','诽谤 → 含有诽谤内容的']],'a slanderous remark 是中伤性言论；a slanderous claim 是被认为不实且损害名誉的说法。指责别人的话是 slanderous，本身也需要事实支持。','slanderous remarks；a slanderous claim；slanderous allegations。','insulting 只是侮辱性的；slanderous 更突出不实的名誉损害，不是所有难听的话都属于同一种性质。',('She demanded an apology for the slanderous remarks.','她要求对方为那些中伤言论道歉。'),('The editor removed an unsupported, slanderous claim from the draft.','编辑从稿件中删去了一项无根据的诽谤性说法。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/slanderous','https://en.wiktionary.org/wiki/slanderous#English']),
]
