DEFERRED={'gelignite':'较专门炸药名，通用学习暂略。','gelation':'较专门凝胶形成术语，优先 gel、congeal。','gelid':'少见书面形容词，优先 icy、freezing。','congelation':'较少用凝冻结成名词，暂略。','gelifluction':'专门冻土地貌术语，暂略。','jellification':'较少用成胶名词，暂略。','gelée':'少见法语食品借词，优先 jelly。','hypersphere':'专门高维几何词，暂略。','pseudosphere':'专门几何曲面术语，暂略。','spherics':'较冷门球面几何术语，暂略。','spherometer':'专门测量仪器名，暂略。','spherulite':'专门矿物、材料结构术语，暂略。','trimetasphere':'冷门专门名称，暂不作通用学习词。','ave':'问候词接拉丁 avere 安好；与本页 avere 渴望不应凭同形合并。','avarous':'古旧或罕用贪婪形容词，优先 avaricious。'}
def rootwords(i):return [w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED]
def rootexclude(i):return {w:DEFERRED[w] for w in list(ASSIGN['roots'][i]['family'])+ASSIGN['roots'][i]['unmatched'] if w in DEFERRED}
GEL_ROOT=dict(id='C0473',meaning='冻结；凝结；胶冻状',core='原来会流动的东西，慢慢变成能保持形状的一团；英语又把这种成形感借给计划和团队。',image='拉丁 gelu 霜冻 → gelare 凝冻；法语 gelée → jelly → jell、jellied；意大利 gelatina → 法语 gélatine → gelatine / gelatin → gel；意大利 gelato → gelato、gelati。',intro='jelly 常是凝冻食品，gelatin 是制作它时可能用到的明胶，gel 是更广的胶状形态。gelato 是冰淇淋：几个名字都带凝冻背景，却不能据此认定它们材料、做法相同。',forms='gel 读 /dʒel/，jell 与它同音但由 jelly 逆构。gelatinous 主重音移到 /læt/；gelatine 常见尾音 /tiːn/。jellied 来自 jelly，jelled 则来自 jell。',branches=[['食品与材料','jelly, gelatin, gelatine, gelatinous'],['凝结、逐渐成形','congeal, gel, jell'],['冷冻甜点及复数','gelato, gelati'],['凝冻的做法与状态','jellied']],contrasts='gelatin 是材料，gel 是形态；gel 不一定含 gelatin。英式 jelly 与美式 jelly 所指食品常不同。gelato 不等于果冻。',practice='用一句话区分 jelly、gelatin 和 gel；解释 The team began to gel；比较 jellied 与 jelled 的拼写来源。',words=rootwords(125),exclude=rootexclude(125))
PI_ROOT=dict(id='C1038',meaning='虔敬；尽责；慈爱与怜悯',core='把应尽的责任认真放在心上，向神是虔敬，向受苦的人可以是慈悲；这条历史后来分成不同常用词。',image='拉丁 pius → pietas → 古法语 piete / pite → piety 虔诚、pity 怜悯；in- + pius → impius、impietas → impious、impiety；piare 赎罪 → expiare → expiate、expiation。',intro='pity 与 piety 曾共享较多意思，如今 pity 常说怜悯或可惜，piety 更常说虔诚。pitiful 是让人觉得可怜，pitying 是看着别人觉得可怜，pitiless 是没有怜悯。辨清这个方向，比只背同一个中文词根更有用。',forms='pity 加 -ful、-less 时 y 变 i；加 -ing 则保留 y。impious 有两种常见重音读法。piety、impiety、expiation 都有独立借入历史，不能只凭后缀认定英语形容词或动词先出现。',branches=[['同情与遗憾','pity'],['可怜的人事与看人的态度','pitiful, pitifully, pitiable, pitying'],['不肯怜悯','pitiless, pitilessly'],['虔诚与不敬','pious, piously, piety, impious, impiety'],['弥补过错','expiate, expiation']],contrasts='pitiful 与 pitying 的同情方向不同；pitiless 不是值得怜悯。pious、piously 有时讽刺假正经，要看上下文。expiate 强调补偿，不等于只说一句道歉。',practice='用 pity 分别说同情与可惜；比较 a pitiful sight、a pitying look、a pitiless judge；说明为什么 expiation 不能简单画成后来英语动词派生。',words=rootwords(126),exclude=rootexclude(126))
SPHER_ROOT=dict(id='C1388',meaning='球；球面；包围的圈层；活动范围',core='一个球既有形状，也能包围出一片空间；因此词族从球形走到地球圈层，又走到人的活动领域。',image='希腊 sphaira 球 → 拉丁 sphaera → sphere；hemi- 半 → hemisphere；现代 atmo- 气、strato- 层、tropo- 转动、meso- 中间、exo- 外 + -sphere → 大气相关名称。',intro='sphere 可以是玻璃球，也可以是职责范围。hemisphere 说半球；spherical 说球形。atmosphere 既是大气，也能说房间氛围。其他圈层词多是近代用古典成分命名，不是古代就已有这些科学分类。',forms='sph 通常读 /sf/。sphere 的元音与 spherical 常见读法不完全一样；atmospheric、hemispheric 的主重音落在后部。a- 在 aspheric 是否定球面，并不等于平面。',branches=[['形状与范围','sphere, spherical, spheroid'],['一半及其关系','hemisphere, hemispheric, hemispherical'],['整体大气与氛围','atmosphere, atmospheric'],['大气的不同层','troposphere, tropospheric, stratosphere, stratospheric, mesosphere, exosphere'],['其他地球圈层','biosphere, hydrosphere'],['非球面光学','aspheric']],contrasts='circle 是平面圆，sphere 是球形。hemispherical 常说形状，hemispheric 常说关联范围。科学中的圈层不是都有硬边界，也不是每个 -sphere 都是实体球壳。',practice='用 sphere 说一件具体物体和一个抽象范围；把大气层名里的前半部分与相对位置联系起来；解释 atmospheric film 为何不必与天气有关。',words=rootwords(127),exclude=rootexclude(127))
AV_ROOT=dict(id='C0103',meaning='热切想要；渴求',core='同样是强烈想要，放在知识和兴趣上可以是热爱，放在财富的过度占有上就会变成贪婪。',image='拉丁 avere 渴望 → avidus → 法语 avide → avid；aviditas → avidity。另一支 avarus 贪婪 → avaritia → avarice；法语 avaricios → avaricious。',intro='an avid reader 往往是赞美爱读书；avaricious 却通常批评贪财。avidity 比 avid 在英语中的记录更早，所以熟悉现代后缀以后，还要记得词史并不总按词长排列。',forms='avid、avidly 重音在开头；avidity 移到 /vɪd/，avaricious 移到 /rɪʃ/。avidity 不是必须由英语 avid 新造，名词有较早借入路线。',branches=[['强烈兴趣','avid, avidly, avidity'],['贪财与占有欲','avarice, avaricious, avariciously']],contrasts='avid 可以正面，avaricious 通常负面；thrifty 节俭也不等于 avaricious。问候语 ave 的直接拉丁来源是安好，不能凭 avere 同形就并入渴望支线。',practice='分别用 avid 和 avaricious 描写两个人；解释 avidly 与 quickly 的差别；说清 avidity 为什么不能只按现代形容词加后缀讲历史。',words=rootwords(128),exclude=rootexclude(128))
SCANDAL_ROOT=dict(id='C1269',meaning='陷阱；绊脚物；冒犯与名誉受损',core='先是让人跌倒的东西，后来比喻让人在道德或名誉上跌一跤，再发展成丑闻、愤慨和诽谤。',image='希腊 skandalon → 拉丁 scandalum → 法语 scandale → scandal；古法语 esclandre → slander。并列形容词 scandalosus → scandalous，动词 scandalizare → scandalize。',intro='scandal 是丑闻，scandalous 是事情令人愤慨，scandalized 是人感到被冒犯。slander 与 scandal 同源，却专门说不实的名誉攻击，不能因为有共同历史就把现代含义混为一谈。',forms='scandal、scandalous、scandalize 的第一音节重读。slander 的英美元音常不同。scandalous 和 scandalize 都有独立借入历史，不能只画成现代 scandal 后面接后缀。',branches=[['公众丑闻','scandal'],['引起愤慨与感到愤慨','scandalize, scandalized'],['对事物的强烈负面评价','scandalous, scandalously'],['不实的名誉攻击','slander, slanderous']],contrasts='scandalous 形容引发反应的事，scandalized 形容作出反应的人。slander 不等于任何尖锐批评；它强调不实且损害名誉。scandal 的远古来源并非每一步都确定，已知希腊起点足够支撑理解。',practice='用 scandalous 与 scandalized 写出同一件事的两面；比较 criticism、rumour、slander；解释 scandal 与 slander 为什么同源却不能互换。',words=rootwords(129),exclude=rootexclude(129))
